css:
/* one sans face for the interface, Chinese in PingFang */
body, .composer-tiptap, [data-user-message-bubble] { font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Hiragino Sans GB", sans-serif; }
/* assistant replies: serif for Latin text, PingFang for Chinese */
[data-message-role="assistant"] .chat-markdown { font-family: ui-serif, "New York", Georgia, "PingFang SC", "Hiragino Sans GB", serif; font-size: 1.0625em; line-height: 1.7; }
[data-message-role="assistant"] .chat-markdown code, .chat-markdown-codeblock { font-family: ui-monospace, "SF Mono", Menlo, monospace; font-size: 0.88em; }

/* status colors: working uses clay instead of blue */
html:root { --info: #c6613f; --info-foreground: #b5573a; --ring: #b8b5a9; --chat-composer-outline: #dedbd0; }
html.dark:root { --info: #d97757; --info-foreground: #e08a6d; --ring: #5e5d59; --chat-composer-outline: #3a3936; }

/* composer: soft card with a quiet border, no colored focus ring */
[data-slot="composer-host"] { border-radius: 1.25rem !important; box-shadow: 0 0.25rem 1.25rem rgb(0 0 0 / 4%), 0 0 0 0.5px rgb(0 0 0 / 6%) !important; }
.dark [data-slot="composer-host"] { box-shadow: 0 0.25rem 1.25rem rgb(0 0 0 / 30%) !important; }
[data-slot="composer-host"]:focus-within { box-shadow: 0 0.25rem 1.5rem rgb(0 0 0 / 6%), 0 0 0 1px #c2bfb3 !important; }
.dark [data-slot="composer-host"]:focus-within { box-shadow: 0 0.25rem 1.5rem rgb(0 0 0 / 35%), 0 0 0 1px #5e5d59 !important; }

[data-slot="composer-host"]::after { border-color: transparent !important; }

/* bottom of the chat: an opaque composer on a solid band, so messages don't show through */
[data-chat-composer-overlay] { background: linear-gradient(to bottom, transparent, var(--background) 1.5rem); }
[data-slot="composer-host"]::before { background: var(--app-theme-surface-raised) !important; backdrop-filter: none !important; }
/* every layer of the composer card uses the card's corner radius */
[data-slot="composer-host"]::before, [data-slot="composer-host"]::after, [data-slot="composer-shell"]::before { border-radius: inherit !important; }
[data-slot="composer-shell"] { border-radius: 1.25rem; }
/* the row under the composer (device, checkout, branch) sits on the band, not in a frosted box */
[data-slot="composer-shell"]::before { background: transparent !important; backdrop-filter: none !important; }

/* stop button: dark round button like Claude's, instead of red */
[data-chat-composer-form] button[class*="bg-destructive"] { background: #141413 !important; color: #faf9f5 !important; box-shadow: none !important; }
.dark [data-chat-composer-form] button[class*="bg-destructive"] { background: #faf9f5 !important; color: #141413 !important; }

[data-user-message-bubble] { border-radius: 0.875rem !important; }
[data-thread-item] [role="button"] { border-radius: 0.625rem; }
[data-slot="dialog-popup"], [data-slot="popover-popup"], [data-slot="menu-popup"] { border-radius: 0.875rem !important; }
